import{_ as a,o as i,c as t,ae as r}from"./chunks/framework.CK6jtcgr.js";const h=JSON.parse('{"title":"Provider Safety and Capability Eligibility","description":"","frontmatter":{},"headers":[],"relativePath":"guide/provider-safety-and-capability-eligibility.md","filePath":"guide/provider-safety-and-capability-eligibility.md"}'),o={name:"guide/provider-safety-and-capability-eligibility.md"};function l(n,e,s,c,d,p){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="provider-safety-and-capability-eligibility" tabindex="-1">Provider Safety and Capability Eligibility <a class="header-anchor" href="#provider-safety-and-capability-eligibility" aria-label="Permalink to &quot;Provider Safety and Capability Eligibility&quot;">​</a></h1><p>Provider connections are not only technical integrations. They are trust boundaries.</p><h2 id="capability-states" tabindex="-1">Capability states <a class="header-anchor" href="#capability-states" aria-label="Permalink to &quot;Capability states&quot;">​</a></h2><p>Providers can occupy explicit states such as:</p><ul><li>not connected</li><li>connecting</li><li>connected</li><li>needs re-auth</li><li>limited capability</li><li>failed test</li><li>revoked</li></ul><h2 id="eligibility-rule" tabindex="-1">Eligibility rule <a class="header-anchor" href="#eligibility-rule" aria-label="Permalink to &quot;Eligibility rule&quot;">​</a></h2><p>Not every actor and not every surface must be allowed to attach every capability.</p><h2 id="safety-examples" tabindex="-1">Safety examples <a class="header-anchor" href="#safety-examples" aria-label="Permalink to &quot;Safety examples&quot;">​</a></h2><h3 id="provider-self-connection" tabindex="-1">Provider self-connection <a class="header-anchor" href="#provider-self-connection" aria-label="Permalink to &quot;Provider self-connection&quot;">​</a></h3><p>Adult self-managed accounts may connect providers directly.</p><p>Minor or supervised accounts require stronger constraints.</p><h3 id="browser-automation" tabindex="-1">Browser automation <a class="header-anchor" href="#browser-automation" aria-label="Permalink to &quot;Browser automation&quot;">​</a></h3><p>Browser-driven login and capability recovery may require additional human oversight because the auth boundary is more fragile and more privacy-sensitive.</p><h3 id="local-runtime" tabindex="-1">Local runtime <a class="header-anchor" href="#local-runtime" aria-label="Permalink to &quot;Local runtime&quot;">​</a></h3><p>Local runtime may be appropriate for private or offline work, but it is not a default capability for every participant class.</p><h3 id="elevated-domains" tabindex="-1">Elevated domains <a class="header-anchor" href="#elevated-domains" aria-label="Permalink to &quot;Elevated domains&quot;">​</a></h3><p>Medical, legal, and other elevated domains require stricter role, trust, and explanation controls.</p><h2 id="product-consequence" tabindex="-1">Product consequence <a class="header-anchor" href="#product-consequence" aria-label="Permalink to &quot;Product consequence&quot;">​</a></h2><p>The public site and product docs must describe not only what providers exist, but which capability classes are appropriate for which users and surfaces.</p>',19)])])}const b=a(o,[["render",l]]);export{h as __pageData,b as default};
